// Packs the album model into a JS module so hosts that refuse .glb files
// still deliver the book. Run after changing assets/book.glb.
import { readFile, writeFile } from 'node:fs/promises';
const glb = await readFile(new URL('../assets/book.glb', import.meta.url));
await writeFile(new URL('../assets/book-glb.js', import.meta.url),
    '// Generated by tools/embed-book.mjs from assets/book.glb.\nexport default ' + JSON.stringify(glb.toString('base64')) + ';\n');
console.log('embedded', glb.length, 'bytes');
